    const wxEvent = {id:'wx-event-1',accountId:'wx-self',groupId:'wx-room',senderId:'wx-member',senderName:'虚构老师',text:'报名通知：2026年11月1日前报名活动',sentAt:'2026-10-18T10:00:00+08:00'};
    assert.equal((await fetch(config.wechatUrl,{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${config.token}`},body:JSON.stringify(wxEvent)})).status,204);
    await wait('document.querySelectorAll("[data-chat-review]").length===4');
    await Promise.all([2,3,4].map(index=>fetch(config.wechatUrl,{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${config.token}`},body:JSON.stringify({...wxEvent,id:`wx-event-${index}`,text:`报名通知 ${index}：请报名活动`})})));
